<?php $xtreampiServer = is_array($rServer ?? null) ? $rServer : []; $xtreampiId = intval($xtreampiServer['id'] ?? 0); ?>
<section class="sc-settings"><div class="sc-page-heading"><div><p class="sc-eyebrow">Infrastructure</p><h1><?php echo htmlspecialchars((string) ($xtreampiServer['server_name'] ?? 'Server'), ENT_QUOTES, 'UTF-8'); ?></h1></div><div class="sc-page-actions"><a class="sc-button sc-button-secondary" href="servers"><i class="fe-chevron-left" aria-hidden="true"></i> Back to servers</a><a class="sc-button sc-button-secondary" href="server_view?id=<?php echo $xtreampiId; ?>&admin_ui=legacy">Open full monitor</a></div></div><div class="sc-data-panel"><div class="sc-settings-list"><div class="sc-settings-row"><span>Server ID</span><strong>#<?php echo $xtreampiId; ?></strong></div><div class="sc-settings-row"><span>Address</span><strong><?php echo htmlspecialchars((string) ($xtreampiServer['server_ip'] ?? '—'), ENT_QUOTES, 'UTF-8'); ?></strong></div><div class="sc-settings-row"><span>Type</span><strong><?php echo intval($xtreampiServer['server_type'] ?? 0) === 0 ? 'Streaming server' : 'Proxy server'; ?></strong></div><div class="sc-settings-row"><span>Status</span><strong><?php echo !empty($xtreampiServer['server_online']) ? 'Online' : 'Offline'; ?></strong></div><div class="sc-settings-row"><span>CPU</span><strong><?php echo htmlspecialchars((string) ($rWatchdog['cpu'] ?? '—'), ENT_QUOTES, 'UTF-8'); ?></strong></div><div class="sc-settings-row"><span>Memory</span><strong><?php echo htmlspecialchars((string) ($rWatchdog['total_mem_used_percent'] ?? '—'), ENT_QUOTES, 'UTF-8'); ?></strong></div><div class="sc-settings-row"><span>Network capacity</span><strong><?php echo number_format((float) ($xtreampiServer['network_guaranteed_speed'] ?? 0)); ?> Mbps</strong></div><div class="sc-settings-row"><span>TLS certificate</span><strong><?php echo !empty($rCertValid) ? 'Valid until ' . htmlspecialchars((string) $rExpiration, ENT_QUOTES, 'UTF-8') : htmlspecialchars((string) ($rExpiration ?? 'Not installed'), ENT_QUOTES, 'UTF-8'); ?></strong></div></div></div></section>
